// Expand watchlist jadi satu item per token
const wl = $json.watchlist;
const out = [];
for (const t of wl) {
  out.push({ json: { nama: t.nama, chain: t.chain, pair: t.pair, threshold: $json.threshold_persen } });
}
return out;

// Parse harga + cek threshold
const pair = $json.pair || $json.pairs?.[0];
if (!pair) return [{ json: { error: 'pair tidak ditemukan' } }];

const nama = $('Pecah Per Token').item.json.nama;
const threshold = $('Pecah Per Token').item.json.threshold;

const price = parseFloat(pair.priceUsd || 0);
const chg = parseFloat(pair.priceChange?.h24 || 0);
const liq = parseFloat(pair.liquidity?.usd || 0);
const vol = parseFloat(pair.volume?.h24 || 0);
const mcap = parseFloat(pair.marketCap || pair.fdv || 0);

const rp = n => '$' + Number(n).toLocaleString('en-US', { maximumFractionDigits: 2 });
const pecah = Math.abs(chg) >= threshold;

let pesan = '';
if (pecah) {
  const arah = chg > 0 ? '🚀 NAIK' : '🔻 TURUN';
  pesan = arah + ' *' + nama + '*\n\n';
  pesan += 'Harga: ' + rp(price) + '\n';
  pesan += 'Perubahan 24j: *' + chg.toFixed(2) + '%*\n';
  pesan += 'Volume 24j: ' + rp(vol) + '\n';
  pesan += 'Likuiditas: ' + rp(liq) + '\n';
  if (mcap > 0) pesan += 'Market Cap: ' + rp(mcap) + '\n';
  pesan += '\nWaktu: ' + new Date().toISOString();
}

return [{
  json: {
    nama, price, change_24h: chg, liquidity: liq, volume_24h: vol,
    market_cap: mcap, pecah, pesan
  }
}];
